# owner: platform
"""Lay students out in seating rows by last name."""

from typing import Iterable, List, Tuple

from rosterkit.models import Student

def name_order(student: Student) -> Tuple[str, str]:
    """Sort key: last name, then first, ignoring case."""
    last = student.last_name.casefold()
    first = student.first_name.casefold()
    return (last, first)

def check_seats(seats: int) -> None:
    """Refuse seat counts that cannot make a row."""
    if seats <= 0:
        raise ValueError(f"seats must be positive: {seats}")

def by_name(students: Iterable[Student]) -> List[Student]:
    """Sort by name, refusing an empty roster."""
    ordered = sorted(students, key=name_order)
    if not ordered:
        raise ValueError("no students to seat")
    return ordered

def split_rows(
    ordered: List[Student], size: int
) -> List[List[Student]]:
    """Cut an ordered list into rows of at most size."""
    rows = []
    for start in range(0, len(ordered), size):
        rows.append(ordered[start : start + size])
    return rows

def format_seat_row(
    number: int, members: List[Student]
) -> str:
    """One text line for a row, names separated by bars."""
    names = [member.display_name for member in members]
    return f"Row {number}: " + " | ".join(names)

def seat_rows(
    students: Iterable[Student], seats_per_row: int
) -> List[str]:
    """One line of text per row, ordered by last name."""
    check_seats(seats_per_row)
    rows = split_rows(by_name(students), seats_per_row)
    numbered = enumerate(rows, start=1)
    return [format_seat_row(n, row) for n, row in numbered]
